erties":{"schema":{"const":"trivium.review.v1"},"verdict":{"enum":["approve","approve-with-nits","request-changes","block"],"description":"整体判断"},"summary":{"type":"string","minLength":1,"description":"不超过 8 行的总判断，先说最危险的一条"},"findings":{"type":"array","description":"空数组合法，表示该侧未发现问题；但元数据会标 empty_review: true，文件照常落盘","items":{"type":"object","required":["id","severity","layer","kind","location","problem","evidence","suggestion","confidence"],"additionalProperties":false,"properties":{"id":{"type":"string","pattern":"^[A-Z][A-Z0-9]*-(r[0-9]+-)?[0-9]{2,}$","description":"形状：\u003c前缀\u003e-\u003c两位以上序号\u003e，重跑时追加轮次如 AGY-r2-01。**本 schema 只校形状，不枚举前缀**——「哪些前缀合法、各属哪一家」的唯一来源是 agents/registry.ts（纪律 7）。前缀是否属于本侧由 parse.ts 的 checkReviewIntegrity 按注册表判定，不合则 guard 记 integrity 问题。此前这里写死 ^(AGY|GLM)-，第三家审核者的合法结论会被 ajv 拒掉、整份结论退化成 parse_fallback——而 schema 文件同时是交给厂商 CLI 的生成约束，运行时改写它会让文件与校验器分叉，所以只能在文件里放开。"},"severity":{"enum":["blocker","major","minor","nit"]},"layer":{"enum":["requirement","plan","code","rca"]},"kind":{"enum":["correctness","security","concurrency","contract","test-gap","maintainability","scope-drift","performance"]},"location":{"type":"string","minLength":1,"description":"如 src/auth/oidc.ts:88 或 plan §3.2"},"problem":{"type":"string","minLength":1},"evidence":{"type":"string","minLength":1,"description":"读了哪些文件/跑了哪些命令/为什么成立。引用的文件必须出现在 consulted 中"},"suggestion":{"type":"string","minLength":1,"description":"修复方向。禁止给出大段可粘贴补丁"},"confidence":{"enum":["high","medium","low"]}}}},"agreed":{"type":"array","items":{"type":"string"},"description":"认为正确的部分，防止只挑刺"},"not_covered":{"type":"array","items":{"type":"string"},"description":"本次未覆盖的范围，暴露盲区。必填"},"consulted":{"type":"array","items":{"type":"string"},"description":"实际读过的项目文件相对路径，与工具轨迹交叉核对（§11.4）"}}}}}
