diff --git a/src/stack.js b/src/stack.js
index 8ef139f..84d9490 100644
--- a/src/stack.js
+++ b/src/stack.js
@@ -2,5 +2,6 @@ export class BoundedStack {
   constructor(capacity) { this.capacity = capacity; this.items = []; }
   push(value) { if (this.items.length >= this.capacity) throw new RangeError("stack full"); this.items.push(value); }
   pop() { return this.items.pop(); }
+  peek() { return this.items[this.items.length - 1]; }
   get size() { return this.items.length; }
 }
diff --git a/test/stack.test.js b/test/stack.test.js
index fae0f74..cd7d8a4 100644
--- a/test/stack.test.js
+++ b/test/stack.test.js
@@ -2,3 +2,5 @@ import {test} from 'node:test';
 import assert from 'node:assert/strict';
 import {BoundedStack} from '../src/stack.js';
 test('容量与后进先出',()=>{const s=new BoundedStack(1);s.push(3);assert.throws(()=>s.push(4),RangeError);assert.equal(s.pop(),3);assert.equal(s.size,0);});
+test('peek 返回栈顶且不改 size',()=>{const s=new BoundedStack(2);s.push(1);s.push(2);assert.equal(s.peek(),2);assert.equal(s.size,2);assert.equal(s.peek(),2);assert.equal(s.pop(),2);});
+test('空栈 peek 返回 undefined',()=>{const s=new BoundedStack(2);assert.equal(s.peek(),undefined);s.push(9);assert.equal(s.pop(),9);assert.equal(s.peek(),undefined);});

